pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));

        vm.deal(address(c), 1 ether);

        vm.deal(actor, 1 ether);

        uint256 bounded = amount % (address(c).balance + 1);

        vm.prank(actor);
        try c.sendMoney(actor, bounded) {
        } catch {
        }

        address owner = address(this);

        if (actor != owner) {
            assertTrue(address(c).balance == 1 ether);
        } else {
            assertTrue(address(c).balance <= 1 ether);
        }
    }
}
